export function spriteRects(width,height,settings){let {cols=1,rows=1,count=1,zoom=1,x=50,y=50,start=0}=settings;for(let n of [cols,rows,count,start])if(!Number.isInteger(n))throw Error('La grille et le nombre de vues doivent être entiers.');if(cols<1||rows<1||cols>256||rows>256||count<1||count>4096||start<0||start+count>cols*rows)throw Error('Le nombre de vues dépasse les cases disponibles.');if(!Number.isFinite(zoom)||zoom<1||zoom>8||![x,y].every(n=>Number.isFinite(n)&&n>=0&&n<=100))throw Error('Cadrage invalide.');if(width<cols||height<rows)throw Error('Grille plus fine que les pixels de l’image.');let cw=width/cols,ch=height/rows,w=cw/zoom,h=ch/zoom;return Array.from({length:count},(_,i)=>{let cell=start+i;return{x:(cell%cols)*cw+(cw-w)*x/100,y:Math.floor(cell/cols)*ch+(ch-h)*y/100,w,h}})}
